  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C52","C58","C59","C63","C65","C67","C70","C72","C74","C75","C77","C83","C86"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C52","C58","C59","C63","C65","C67","C70","C72","C74","C75","C77","C83","C86"],
  "claims": [
    {
      "claim": "The query is an aminocephalosporin with the same alpha-amino p-hydroxyphenylacetamido side chain as PEPT1-transported beta-lactams; L5 records identify cefadroxil, cephalexin, and ceftibuten as PEPT1 substrates, supporting carrier-mediated intestinal absorption despite low passive permeability.",
      "card_ids": ["C67","C72","C74"]
    },
    {
      "claim": "Meropenem Caco-2 data show absorptive Papp A→B of 2.63–2.92×10^-6 cm/s and B→A of 1.47×10^-6 cm/s, indicating no net secretory efflux for this beta-lactam class.",
      "card_ids": ["C65","C70","C75"]
    },
    {
      "claim": "Amoxicillin solubility of 4.4–7.69 mg/mL at pH 1.2–6.8 and cephalexin Caco-2 permeability of 8.42×10^-7 cm/s support dissolution and intestinal absorption for the query's structural class.",
      "card_ids": ["C52","C58","C59","C63"]
    },
    {
      "claim": "L6 hepatic-clearance records for cephalosporins show low-to-modest hepatic elimination: cefuzonam IPRL CLint 0.905 mL/min/g and cefoperazone hepatic clearance 3.65–4.16 mL/min in rat liver-kidney perfusion; these do not support a high first-pass hepatic loss for the query.",
      "card_ids": ["C77","C83","C86"]
    },
    {
      "claim": "No L6 record affirmatively demonstrates F < 20%; the hepatic-clearance/metabolic-stability family is mechanistically supportive or neutral, so the high prediction is retained and strengthened.",
      "card_ids": ["C77","C83","C86"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C77","C83","C86"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for cefatrizine or the exact query context is supplied.",
    "No PEPT1-specific uptake assay on the query itself; carrier-mediated absorption is inferred from structure and class behavior.",
    "No quantitative hepatic first-pass extraction or metabolic stability measurement for the query; L6 records are for other cephalosporins in rat/human systems.",
    "Fasted-state human PK for the query is not directly measured; L3 exposure records are nonfasting or unspecified.",
    "Dose, formulation, and renal clearance contributions for the query are unknown."
  ],
  "decision_summary": "L6 hepatic-clearance/metabolic-stability records show low-to-modest hepatic elimination for cephalosporins and no high first-pass metabolism; combined with PEPT1-mediated uptake, adequate solubility, and no net efflux, F>=20% remains better supported. Prediction high, confidence high, strengthened."
}

